static void test_oob_array_get(void)
{
    Array a = array_new(sizeof (int));
    int *val;

    if (!a)
        exit(1);

    val = array_add(a);
    if (val)
        *val = 42;

    if (array_get(a, -1) != NULL)
        exit(1);

    if (array_get(a, 1) != NULL)
        exit(1);

    if (array_get(a, 100) != NULL)
        exit(1);

    array_free(a);
}

