static void test_alloc_del_shrink_safety(void)
{
    Array a = array_new(sizeof (int));
    int i;

    if (!a)
        exit(1);

    for (i = 0; i < 100; i++)
    {
        int *val = array_add(a);
        if (!val)
            exit(1);
        *val = i;
    }

    for (i = 0; i < 99; i++)
        array_del(a);

    if (array_len(a) != 1)
        exit(1);

    if (*(int *) array_get(a, 0) != 0)
        exit(1);

    array_free(a);
}

